def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/wildfire/input/noaa_wildfires_monthly_stats.csv'
    # Skip metadata lines; actual header starts at line 4 (1-indexed)
    df = pd.read_csv(path, skiprows=3)
    return pd.concat([df.head(3), df.tail(3)], ignore_index=True)

def process(nifc) -> pd.DataFrame:
    import pandas as pd
    df = nifc.copy()
    df.columns = [c.strip() for c in df.columns]
    return pd.DataFrame({
        'n_cols':[df.shape[1]],
        'col_names':[list(df.columns)],
        'dtypes':[df.dtypes.astype(str).to_dict()],
        'head_row':[df.head(1).to_dict(orient='records')[0]]
    })

def process(noaa) -> pd.DataFrame:
    import pandas as pd
    df = noaa.copy()
    # Date is YYYYMM
    df['Year'] = (df['Date'] // 100).astype(int)
    out = df.groupby('Year', as_index=False).agg(
        noaa_fires=('Number of Fires', 'sum'),
        noaa_acres=('Acres Burned', 'sum')
    )
    return out.sort_values('Year')

def process(annual_diffs) -> pd.DataFrame:
    import pandas as pd
    # Pearson correlation between annual differences
    df = annual_diffs.copy()
    corr = df['diff_fires'].corr(df['diff_acres'])
    return pd.DataFrame([{'corr_diff_fires_vs_diff_acres': corr}])
